ECONOMIC_COMPENSATION.conversion:
const start = get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from);
const end = add_days(ctx.entry.incurred_on, 1);
const months = calendar_completed_months(start, end);
const years = Math.trunc(months / 12);
const remainder = months % 12;
const part =
	remainder >= 6 ? 1 :
	remainder > 0 || add_months(start, months) < end ? 0.5 :
	0;
const count = years + part;
// 劳动合同法 第四十七条第二款: the 3× wage and the 12-year cap bind only a wage above 3× the local monthly average
const wage = Number(ctx.entry.quantity);
const code = get(
	ctx.subject.employer,
	'entity_extension_data.region',
	get(ctx.subject.employer, 'source_reference', '')
);
const cap = first(ctx.lookup.average_wage_cap.filter((row) => row.code === code));
if (wage <= cap.monthly) return wage * count;
return cap.monthly * Math.min(12, count);

DAMAGE_COMPENSATION_DEDUCTION.conversion:
const wage = get(ctx.subject.employment, 'terms.rate.amount');
if (wage == null) return ctx.entry.quantity;
const ext = get(ctx.subject.employer, 'entity_extension_data', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const zone = worksite !== '' && worksite !== employerRegion
  ? String(get((ctx.lookup.minimum_wage_by_zone || []).find((row) => row.region === region), 'default_zone', '1'))
  : String(get(ext, 'wage_zone', '1'));
const table = (ctx.lookup.minimum_wage_by_zone || []).find((row) => row.region === region && row.zone === zone);
const floor = Number(get(table, 'monthly', 0));
const cap = Math.min(Number(wage) * ctx.lookup.max_share_of_wage, Math.max(0, Number(wage) - floor));
return Math.min(ctx.entry.quantity, cap);

