FIXED_ALLOWANCE.conversion:
// 工资支付暂行规定 第十一条、第十二条: no wage for days not worked. A fixed allowance is paid for the days the salary pays: it falls by the period's paid share on its own line, and BASIC stays the salary alone.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const rate = Number(get(terms, 'rate.amount', 0));
const amount = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const coverage = ctx.run.salary_coverage;
const off = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
let working = 0;
for (let date = coverage.from; date <= coverage.to; date = add_days(date, 1)) if (!off.includes(weekday(date))) working += 1;
const hours = working * Number(get(terms, 'normal_hours_per_day', 8));
const salary = unit === 'DAILY' ? rate * working : unit === 'HOURLY' ? rate * hours : rate;
return salary > 0 ? amount * ctx.paid_share : amount;

HIGH_TEMPERATURE_ALLOWANCE.eligibility:
const employerRegion = String(get(ctx.subject.employer, 'entity_extension_data.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
if (region !== ctx.lookup.region) return false;
if (!ctx.lookup.months.includes(Number(ctx.as_of.slice(5, 7)))) return false;
return (ctx.work_events ?? []).some((event) => {
  if (get(event, 'code', '') !== 'HIGH_TEMPERATURE') return false;
  const from = String(get(event, 'from', ''));
  const to = get(event, 'to', null);
  return from !== '' && from <= ctx.as_of && ctx.as_of <= String(to ?? from);
});

PENSION.eligibility:
const engagement = get(ctx.subject.employment, 'engagement', 'EMPLOYEE');
	const excluded = ['PART_TIME', 'INTERN', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);
	const end = get(ctx.subject.employment, 'effective_range.to', null);
	const ended = end != null && end !== '' && end < ctx.run.salary_coverage.from;
	const exempt = get(ctx.subject.employment, 'employee_extension_data.si_exempt_schemes', []);
	// a monthly charge: an off-cycle run carries only its own items
	if (get(ctx.run, 'kind', 'ON_CYCLE') === 'OFF_CYCLE') return false;
	if (excluded) return false;
	if (ended) return false;
	if (Array.isArray(exempt) && exempt.includes('PENSION')) return false;
	const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
	if (born == null || born === '') return true;
	// 劳动合同法 第四十四条第二项; 劳动合同法实施条例 第二十一条: the labour contract ends at the statutory retirement age, and the scheme stops
	const category =
		get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
			? get(ctx.subject.employment, 'employee_extension_data.retirement_category', 'FEMALE_50')
			: 'MALE';
	const retirement = ctx.lookup.retirement.find((row) => row.category === category);
	const deferred =
		born < retirement.cutoff
			? 0
			: Math.min(
					retirement.max_deferral_months,
					Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1
				);
	const retires = add_months(born, retirement.base_years * 12 + deferred);
	return ctx.run.salary_coverage.from < retires;

