IIT.employee_amount:
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const elections = get(facts, 'statutory.IIT', {});
const term = get(ctx.subject.employment, 'employee_extension_data', {});
// the tax year and its months follow the pay date, as the balances do
const paidOn = get(ctx.run, 'pay_date', ctx.run.salary_coverage.to);
const year = paidOn.slice(0, 4);
const d = ctx.lookup.deductions;
const residency = get(ctx.subject.employment, 'terms.residency_status', 'RESIDENT');
const now = (code) => Number(get(ctx.subtotals, code, 0));
const ytd = (code) => Number(get(ctx.balances, 'ytd.' + code, 0));
const schemes = get(ctx.balances, 'statutory_contribution', {});
const paid = (code) => (Object.hasOwn(schemes, code + '.employee') ? Number(schemes[code + '.employee']) : 0);
const tax_bracket = (rows, value) => {
	const row = rows.find((item) => item.up_to == null || value <= item.up_to);
	return row == null ? 0 : Math.max(0, value * Number(row.rate) - Number(row.quick));
};
// 财政部 税务总局公告2023年第29号: foreign allowances are exempt instead of the special additional deductions, never both
const foreignExempt = get(elections, 'foreign_allowance_exemption', false) === true;
const annualBonus = (read) => read('ANNUAL_BONUS_WAGES') - read('ORDINARY_WAGES');
const taxed = (read) => read(foreignExempt ? 'ADDITIONAL_WAGES' : 'FOREIGN_ALLOWANCES');
// 财政部 税务总局公告2023年第30号: a separately taxed annual bonus stays out of the cumulative base; IIT_ANNUAL_BONUS taxes it
const separate = get(elections, 'annual_bonus_separate', false) === true && residency !== 'NON_RESIDENT';
const wages = taxed(now) - (separate ? annualBonus(now) : 0);
if (residency === 'NON_RESIDENT') {
	const share = Number(get(facts, 'china_workday_share', 1));
	// 个人所得税法 第六条第一款第二项: a non-resident is taxed on the month's income: what an earlier run of this month paid is in the balance.
	const month = get(ctx, 'balances.month', {});
	const paidMonth = paidOn.slice(0, 7);
	const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
	const coverage = ctx.run.salary_coverage;
	const wholeMonth =
		String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
	const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
	const before = (code) => (separate ? 0 : heldIn(code));
	const income = wages + before(foreignExempt ? 'ADDITIONAL_WAGES' : 'FOREIGN_ALLOWANCES');
	return tax_bracket(ctx.lookup.monthly_ladder, Math.max(0, income * share - d.monthly_standard)) - before('IIT.employee');
}
const split = (flag) => (flag === true ? d.shared_share : 1);
const housing =
	get(elections, 'housing_loan_interest', false) === true ? d.housing_loan :
	get(elections, 'housing_rent', false) === true ? d.housing_rent :
	0;
const special =
	Number(get(elections, 'children_education_children', 0)) *
		d.child_education *
		split(get(elections, 'children_education_split', false)) +
	Number(get(elections, 'infant_care_children', 0)) *
		d.infant_care *
		split(get(elections, 'infant_care_split', false)) +
	(get(elections, 'continuing_education_degree', false) === true ? d.continuing_education : 0) +
	housing +
	(get(elections, 'elderly_support_only_child', false) === true
		? d.elderly_sole
		: Math.min(Number(get(elections, 'elderly_support_monthly', 0)), d.elderly_shared));
const ordinary = now('ORDINARY_WAGES');
const other =
	Math.min(Number(get(elections, 'commercial_health_monthly', 0)), d.commercial_health) +
	Math.min(
		Number(get(elections, 'annuity_employee_monthly', 0)),
		d.annuity_share *
			Number(get(term, 'si_contribution_base', null) != null ? term.si_contribution_base : ordinary)
	);
const additional = (foreignExempt ? 0 : special) + other;
const contributions = sum(ctx.lookup.deductible_schemes.map((code) => get(ctx.statutory, code + '.employee', 0)));
const total = (rows, field) => rows.reduce((acc, row) => acc + Number(get(row, field, 0)), 0);
// wage income only: FINAL_PAY settlements, exempt allowances and claims never enter this checkpoint
const priorIncome = taxed(ytd) - (paid('IIT_ANNUAL_BONUS') > 0 ? annualBonus(ytd) : 0);
const priorContributions = sum(ctx.lookup.deductible_schemes.map(paid));
const start = get(ctx.subject.employment, 'employment_started_on', get(ctx.subject.employment, 'effective_range.from', year + '-01-01'));
const from = start > year + '-01-01' ? start : year + '-01-01';
const months = Math.max(1, calendar_completed_months(month_start(from), paidOn) + 1);
// Other withholding agents are reconciled annually, not in this monthly cumulative base.
const declaredPrior = get(term, 'prior_employment', []);
const sameAgent = (Array.isArray(declaredPrior) ? declaredPrior : []).filter(
	(row) =>
		Number(get(row, 'tax_year', 0)) === Number(year) &&
		get(row, 'same_withholding_agent', false) === true
);
const periods = Math.min(12, months + total(sameAgent, 'months'));
// 公告2020年第13号: first wage income of the year deducts 5000 for each month of the year to date
const standardMonths =
	get(elections, 'first_job_in_year', false) === true ? Math.max(periods, Number(paidOn.slice(5, 7))) : periods;
const standard =
	get(elections, 'prior_year_60000', false) === true ? d.annual_standard : d.monthly_standard * standardMonths;
const review = get(elections, 'receipt_deduction_review', null);
let annual = 0;
if (review != null && review.month === paidOn.slice(0, 7)) {
	const pension = Math.min(d.personal_pension_annual, Number(get(review, 'personal_pension_paid_ytd', 0)));
	annual = Math.max(0, pension - Number(get(review, 'personal_pension_deducted_before_month', 0)));
	if (!foreignExempt && Math.trunc(Number(get(review, 'qualification_year', 0))) === Math.trunc(Number(year)))
		annual += Math.max(0, d.qualification_annual - Number(get(review, 'qualification_deducted_before_month', 0)));
}
const cumulative = Math.max(
	0,
	priorIncome +
		total(sameAgent, 'gross_income') +
		wages -
		priorContributions -
		total(sameAgent, 'employee_social_contributions') -
		contributions -
		standard -
		additional * periods -
		annual
);
// 国家税务总局公告2018年第61号 第六条: 余额为负值时，暂不退税, so below zero nothing is paid and the next month's cumulative figure counts it
return tax_bracket(ctx.lookup.annual_ladder, cumulative) - paid('IIT') - total(sameAgent, 'iit_withheld');

IIT_ANNUAL_BONUS.eligibility:
const elections = get(ctx.subject.employment, 'employee_extension_data.statutory.IIT', {});
if (get(elections, 'annual_bonus_separate', false) !== true) return false;
if (get(ctx.subject.employment, 'terms.residency_status', 'RESIDENT') === 'NON_RESIDENT') return false;
return Number(get(ctx.subtotals, 'ANNUAL_BONUS_WAGES', 0)) !== Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));

IIT_ANNUAL_BONUS.employee_amount:
const schemes = get(ctx.balances, 'statutory_contribution', {});
const paid = Object.hasOwn(schemes, 'IIT_ANNUAL_BONUS.employee') ? Number(schemes['IIT_ANNUAL_BONUS.employee']) : 0;
const now = Number(get(ctx.subtotals, 'ANNUAL_BONUS_WAGES', 0)) - Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const before = Number(get(ctx.balances, 'ytd.ANNUAL_BONUS_WAGES', 0)) - Number(get(ctx.balances, 'ytd.ORDINARY_WAGES', 0));
// the one bonus of the year: a later payment under this catalogue is a further tranche of it
const bonus = Math.max(0, now + (paid > 0 ? before : 0));
const row = ctx.lookup.monthly_ladder.find(
	(item) => item.up_to == null || bonus / 12 <= item.up_to
);
return bonus * row.rate - row.quick - paid;

IIT_SEVERANCE.employee_amount:
const code = get(
	ctx.subject.employer,
	'entity_extension_data.region',
	get(ctx.subject.employer, 'source_reference', '')
);
const cap = first(ctx.lookup.average_wage_cap.filter((row) => row.code === code));
const schemes = get(ctx.balances, 'statutory_contribution', {});
const paid = Object.hasOwn(schemes, 'IIT_SEVERANCE.employee') ? Number(schemes['IIT_SEVERANCE.employee']) : 0;
const now = Number(get(ctx.subtotals, 'SEVERANCE', 0)) - Number(get(ctx.subtotals, 'GROSS', 0));
const before = Number(get(ctx.balances, 'ytd.SEVERANCE', 0)) - Number(get(ctx.balances, 'ytd.GROSS', 0));
const taxable = Math.max(0, before + now - cap.monthly * 12);
const row = ctx.lookup.annual_ladder.find((item) => item.up_to == null || taxable <= item.up_to);
return taxable * row.rate - row.quick - paid;

