MINIMUM_WAGE_HOURLY.validate:
const employer = (ctx.reads.entity_profile_version ?? []).find(
  (v) =>
    v.status === 'SEALED' &&
    v.effective_range.from <= ctx.entry.effective_range.from &&
    (v.effective_range.to == null || v.effective_range.to >= ctx.entry.effective_range.from),
);
const ext = get(employer, 'entity_extension_data', {});
const terms = get(ctx.entry, 'terms', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(terms, 'work_region', ''));
// the place of performance governs; the registered place is the fallback
const region = worksite !== '' ? worksite : employerRegion;
const regionRows = (ctx.lookup.minimum_wage_by_zone ?? []).filter((r) => r.region === region);
const zone = worksite !== '' && worksite !== employerRegion
  ? String(get(regionRows[0], 'default_zone', '1'))
  : String(get(ext, 'wage_zone', get(regionRows[0], 'default_zone', '1')));
const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'hourly', 0));
const rate = get(terms, 'rate', {});
const amount = Number(get(rate, 'amount', 0));
const weekly = Number(get(terms, 'normal_hours_per_week', 0)) ||
  Number(get(terms, 'normal_hours_per_day', 8)) * Number(get(terms, 'normal_days_per_week', 5));
const monthlyHours = weekly * 52 / 12;
const hourly = get(rate, 'unit', 'HOURLY') === 'MONTHLY' ? amount / monthlyHours : amount;
return floor > 0 && monthlyHours > 0 && hourly >= floor;

PROBATION_LENGTH.validate:
const probation = ctx.entry.terms.probation_period;
const limits = ctx.lookup.probation_months;
const engaged = ctx.entry.engagement === 'PART_TIME';
const signed = ctx.entry.signed_contract_period;
let months = limits.open_ended;
if (engaged) months = 0;
else if (signed != null) {
  const length = calendar_completed_months(signed.from, add_days(signed.to, 1));
  months =
    length < limits.minimum_contract ? 0 :
    length < limits.medium_contract ? limits.short :
    length < limits.long_contract ? limits.medium :
    limits.long;
}
if (!(months > 0)) return false;
if (!(probation.from >= ctx.entry.effective_range.from)) return false;
return probation.to < add_months(probation.from, months);

PROBATION_WAGE.condition:
