PROBATION_WAGE.validate:
const employer = (ctx.reads.entity_profile_version ?? []).find(
  (v) =>
    v.status === 'SEALED' &&
    v.effective_range.from <= ctx.entry.effective_range.from &&
    (v.effective_range.to == null || v.effective_range.to >= ctx.entry.effective_range.from),
);
const ext = ctx.entry.employee_extension_data ?? {};
const job = get(ext, 'job_salary', null);
const jobValue =
  job == null ? null :
  typeof job === 'number' ? job :
  Number(get(job, 'value', job));
const post = get(ext, 'post_lowest_wage', null);
const rate = Number(ctx.entry.terms.rate.amount);
const comparable =
  jobValue != null ? Number(jobValue) * ctx.lookup.probation_wage_share :
  post != null ? Number(post) :
  null;
const employerExt = get(employer, 'entity_extension_data', {});
const employerRegion = String(get(employerExt, 'region', ''));
const worksite = String(get(ctx.entry.terms, 'work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const regionRows = (ctx.lookup.minimum_wage_by_zone ?? []).filter((r) => r.region === region);
const zone = worksite !== '' && worksite !== employerRegion
  ? String(get(regionRows[0], 'default_zone', '1'))
  : String(get(employerExt, 'wage_zone', get(regionRows[0], 'default_zone', '1')));
const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'monthly', 0));
if (comparable == null) return false;
if (!(floor > 0)) return false;
if (!(rate >= comparable)) return false;
return rate >= floor;

