MEDICAL_PERIOD_EXHAUSTED.validate:
// 劳部发〔1994〕479号 第三条: 医疗期至多24个月; 劳部发〔1995〕236号 第二条: 特殊疾病24个月内不能痊愈的, 经批准可以适当延长.
const catalog = ctx.reads.leave_catalog.find((row) => row.code === ctx.entry.catalog_code);
if (catalog == null || catalog.code !== 'SICK_LEAVE') return true;
const illnesses = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'ILLNESS');
const own = get(ctx.entry, 'leave_catalog_entry_day', []);
const expired = own.some((child) => illnesses.some((event) => event.on <= String(child.incurred_on) && (get(event, 'ended_on', null) == null || String(child.incurred_on) <= event.ended_on) && calendar_completed_months(event.on, String(child.incurred_on)) >= catalog.lookup.medical_period_max_months));
if (expired && get(ctx.subject.employment, 'employee_extension_data.medical_period_extension', null) == null)
  throw 'This illness has run the 24-month medical period. Record the approved extension on the contract first.';
const used =
  sum(
    (ctx.reads.leave_catalog_entry ?? [])
      .filter(
        (e) =>
          e.id !== get(ctx.entry, 'id', '') &&
          e.catalog_code === ctx.entry.catalog_code,
      )
      .map(
        (e) =>
          (ctx.reads.leave_catalog_entry_day ?? []).filter((child) => child.leave_entry_id === e.id).length / 2,
      ),
  ) +
  own.length / 2;
if (used <= ctx.lookup.review_after_days) return true;
return get(ctx.subject.employment, 'employee_extension_data.medical_period_review', null) != null;

WORK_INJURY_LEAVE_12_MONTHS.validate:
