return until !== '' && until >= ctx.entry.work_date;

ROSTER_PREGNANT_NURSING.validate:
const zone = String(get(ctx.subject.employer, 'time_zone', 'Asia/Shanghai'));
const asOf = ctx.entry.work_date + 'T23:59:59Z';
const planned = get(ctx.entry, 'planned_overtime_intervals', []) ?? [];
const actual = get(ctx.entry, 'actual_worked_intervals', []) ?? [];
const night =
  clock_window_minutes(planned, zone, '22:00', '06:00', asOf) +
  clock_window_minutes(actual, zone, '22:00', '06:00', asOf);
return planned.length === 0 && night === 0;

ROSTER_CHILD_LABOUR.validate:
const employment = ctx.subject.employment;
const dob = get(employment.payroll, 'date_of_birth', null);
if (dob == null || dob === '') return false;
if (age_on(dob, ctx.entry.work_date) >= ctx.lookup.minimum_age_years) return true;
return get(employment.employee_extension_data, 'minor_employment_approved', false) === true;

PROBATION_ONCE.validate:
const from = ctx.entry.terms.probation_period.from;
const prior = (ctx.reads.employee_contract ?? []).filter(
  (c) =>
    c.id !== get(ctx.entry, 'id', '') &&
    c.status === 'SEALED' &&
    get(c.terms, 'probation_period', null) != null,
);
return !prior.some((c) => c.terms.probation_period.from !== from);

OPEN_ENDED_REQUIRED.validate:
const prior = (ctx.reads.employee_contract ?? []).filter(
  (c) => c.id !== get(ctx.entry, 'id', '') && c.status === 'SEALED',
);
const earliest = prior
  .map((c) => c.effective_range.from)
  .concat([ctx.entry.effective_range.from])
  .toSorted()[0];
const service = calendar_completed_months(earliest, ctx.entry.signed_contract_period.from);
const required =
  service >= ctx.lookup.service_months ||
  prior.filter((c) => c.signed_contract_period != null).length >=
    ctx.lookup.prior_fixed_terms;
if (!required) return true;
return (ctx.reads.workplace_case_catalog_entry ?? []).some(
  (c) =>
    c.kind === 'FIXED_TERM_CONTRACT_REQUEST' &&
    get(c, 'employment_id', null) === get(ctx.entry, 'id', '') &&
    c.opened_on <= get(c.inputs, 'signed_on', '') &&
    get(c.inputs, 'contract_start', '') === ctx.entry.signed_contract_period.from &&
    get(c.inputs, 'contract_end', '') === ctx.entry.signed_contract_period.to,
);

CONTRACT_CATEGORIES.validate:
const terms = ctx.entry.terms;
return (
  ctx.lookup.work_classifications.includes(
    String(get(terms, 'statutory_work_category', '')),
  ) &&
  ctx.lookup.residency_statuses.includes(String(get(terms, 'residency_status', '')))
);

SHARED_STRUCTURED_EMPLOYEE_INPUTS.validate:
const ext = ctx.entry.employee_extension_data ?? {};
const bad = (ctx.lookup.employee_fields ?? []).some((b) => {
  const value = get(ext, b.field, null);
  if (value == null) return false;
  if (b.minimum != null && Number(value) < b.minimum) return true;
  if (b.maximum != null && Number(value) > b.maximum) return true;
  return b.integer === true && Number(value) !== Math.trunc(Number(value));
});
if (bad) return false;
const retirement = get(ext, 'retirement_category', null);
if (retirement != null && !ctx.lookup.retirement_categories.includes(retirement)) return false;
const schemes = get(ext, 'si_exempt_schemes', []);
if (!Array.isArray(schemes)) return true;
return schemes.every((s) => ctx.lookup.si_exempt_schemes.includes(s));

SHARED_STRUCTURED_ENTITY_INPUTS.validate:
const ext = ctx.entry.entity_extension_data ?? {};
const bad = (ctx.lookup.entity_fields ?? []).some((b) => {
  const value = get(ext, b.field, null);
  if (value == null) return false;
  if (b.minimum != null && Number(value) < b.minimum) return true;
  if (b.maximum != null && Number(value) > b.maximum) return true;
  return b.integer === true && Number(value) !== Math.trunc(Number(value));
});
if (bad) return false;
const zone = get(ext, 'wage_zone', null);
return zone == null || ctx.lookup.wage_zones.includes(zone);

BUSINESS_CASE_SUBJECT_AND_REFERENCE.validate:
const reference = String(
  get(ctx.entry.inputs, 'reference', get(ctx.entry.inputs, 'offer_reference', '')),
).trim();
if (reference !== '') return true;
return ctx.entry.evidence_file != null;

FIXED_TERM_REQUEST_DATES.validate:
const start = String(get(ctx.entry.inputs, 'contract_start', ''));
const end = String(get(ctx.entry.inputs, 'contract_end', ''));
if (start === '') return false;
if (!(end >= start)) return false;
return String(ctx.entry.opened_on) <= start;

RENEWAL_REFUSAL_REVIEW_DATES.validate:
const offered = String(get(ctx.entry.inputs, 'offered_on', ''));
const refused = String(get(ctx.entry.inputs, 'refused_on', ''));
const opened = String(ctx.entry.opened_on);
if (offered === '') return false;
if (refused === '') return false;
if (offered > refused) return false;
if (refused > opened) return false;
return ctx.entry.closed_on == null || String(ctx.entry.closed_on) >= refused;

ANNUAL_LEAVE_FORFEITED.validate:
// 职工带薪年休假条例 第四条第(二)至(五)项: 事假累计20天以上且不扣工资, 或病假累计满2、3、4个月的, 不享受当年年休假.
// 企业职工带薪年休假实施办法 第八条: 已休年休假后年度内才出现上述情形的, 不享受下一年度的年休假.
const own = ctx.reads.leave_catalog.find((row) => row.code === ctx.entry.catalog_code);
const started = get(first(ctx.reads.employee_contract), 'service_started_on', ctx.subject.employment.effective_range.from);
const taken = (code, year) => sum(
  ctx.reads.leave_catalog_entry
    .filter((row) => row.catalog_code === code)
    .map((row) => {
      const dayCount = (ctx.reads.leave_catalog_entry_day ?? []).filter(
        (child) => child.leave_entry_id === row.id && String(child.incurred_on).startsWith(year),
      ).length / 2;
      return dayCount;
    })
);
const barred = (year) => {
  const months = calendar_completed_months(started, year + '-12-31');
  const band = own.lookup.sick_leave_disqualification_days.filter((row) => row.service_months <= months).at(-1);
  return taken('PERSONAL_LEAVE_PAID', year) >= own.lookup.paid_personal_leave_disqualification_days || (band != null && taken('SICK_LEAVE', year) >= band.days);
};
const refused = get(ctx.entry, 'leave_catalog_entry_day', []).some((child) => {
  const year = String(child.incurred_on).slice(0, 4);
  const last = String(Number(year) - 1);
  return barred(year) || (barred(last) && taken('ANNUAL_LEAVE', last) > 0);
});
if (refused) throw 'Personal or sick leave this year, or last year after annual leave was taken, forfeits annual leave.';
return true;

MENSTRUAL_LEAVE_CONDITIONS.validate:
// 上海市女职工劳动保护办法 第八条: 保护作业女职工经期1天公假; 云南省女职工劳动保护特别规定 第九条第三项: 重度痛经确诊后1至2天. One period falls in a calendar month.
const own = ctx.reads.leave_catalog.find((row) => row.code === ctx.entry.catalog_code);
const employerRegion = get(ctx.subject.employer, 'entity_extension_data.region', '');
const worksite = get(ctx.subject.employment, 'terms.work_region', '');
const region = worksite !== '' ? worksite : employerRegion;
const needs = first(own.lookup.requires_by_region.filter((row) => row.region === region));
const grant = first(own.lookup.days_by_region.filter((row) => row.region === region));
if (needs == null || grant == null || get(ctx.subject.employment, 'employee_extension_data.' + needs.requires, false) !== true)
  throw 'This contract does not hold the fact the local rule requires for menstrual leave.';
const slots = get(ctx.entry, 'leave_catalog_entry_day', []);
const rows = ctx.reads.leave_catalog_entry
  .filter((row) => row.id !== get(ctx.entry, 'id', '') && row.catalog_code === own.code)
  .concat([ctx.entry]);
const within = slots.every((child) => {
  const month = String(child.incurred_on).slice(0, 7);
  const taken = sum(rows.map((row) => {
    const held = row.id === ctx.entry.id
      ? slots
      : (ctx.reads.leave_catalog_entry_day ?? []).filter((slot) => slot.leave_entry_id === row.id);
    const dayCount = held.filter((slot) => String(slot.incurred_on).startsWith(month)).length / 2;
    return dayCount;
  }));
  return taken <= grant.days;
});
if (!within) throw 'Menstrual leave is past the days of this calendar month.';
return true;

NURSING_BREAK_CHILD_AGE.validate:
// 女职工劳动保护特别规定 第九条第二款: 哺乳未满1周岁婴儿的女职工.
const own = ctx.reads.leave_catalog.find((row) => row.code === ctx.entry.catalog_code);
const births = get(ctx.subject.employment, 'family', []).filter((member) => member.relation === 'CHILD').map((child) => get(child, 'born_on', null)).filter((born) => born != null && born !== '');
const nursing = get(ctx.entry, 'leave_catalog_entry_day', []).every((slot) => births.some((born) => String(born) <= String(slot.incurred_on) && age_on(String(born), String(slot.incurred_on)) < own.lookup.child_age_limit_years));
if (!nursing) throw 'A nursing break needs a child under one on the contract.';
return true;

ELDER_CARE_HOSPITALISATION.validate:
// 上海市老年人权益保障条例 第二十四条; 云南省老年人权益保障条例 第二十四条: 老年人患病住院治疗期间.
const stays = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'PARENT_HOSPITALISATION');
const inside = get(ctx.entry, 'leave_catalog_entry_day', []).every((slot) => stays.some((event) => event.on <= String(slot.incurred_on) && (get(event, 'ended_on', null) == null || String(slot.incurred_on) <= event.ended_on)));
if (!inside) throw 'Elder-care leave falls only while a parent is in hospital. Record the stay as a PARENT_HOSPITALISATION event on the contract first.';
return true;

HOME_LEAVE_TRAVEL.eligibility:
const end = get(ctx.subject.employment.effective_range, 'to', null);
if (get(ctx.subject.employer.entity_extension_data, 'state_owned', false) !== true) return false;
if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (end === null) return true;
return ctx.entry.incurred_on <= end;

ANNUAL_LEAVE.payout:
// 职工带薪年休假条例 第五条; 企业职工带薪年休假实施办法 第十条: 应休未休的天数按日工资收入的300%支付, 其中包含正常工作期间的工资. 第十二条: 离职时按当年度在本单位已过日历天数折算, 不足1整天不支付.
const range = ctx.subject.employment.effective_range;
const end = get(range, 'to', null);
const started = get(ctx.subject.employment, 'service_started_on', range.from);
const joined = get(ctx.subject.employment, 'employment_started_on', range.from);
if (end == null) return ctx.day_rate * ctx.entry.quantity * ctx.lookup.encashment_factor;
const band = ctx.lookup.service_bands.filter((row) => row.service_months <= calendar_completed_months(started, end)).at(-1);
if (band == null) return 0;
const start = end.slice(0, 4) + '-01-01';
const qualified = add_months(started, ctx.lookup.qualifying_service_months);
const later = joined > qualified ? joined : qualified;
const from = later > start ? later : start;
const part = (to) => Math.floor((band.days * (calendar_distance_days(from, to) + 1)) / ctx.lookup.first_year_proration_days);
const year = from === start ? band.days : part(end.slice(0, 4) + '-12-31');
return ctx.day_rate * Math.max(0, ctx.entry.quantity - year + part(end)) * ctx.lookup.encashment_factor;

lookup.entitlement:
// 职工带薪年休假条例 第三条: 累计工作满1年5天, 满10年10天, 满20年15天. 企业职工带薪年休假实施办法 第五条: 新进用人单位且连续工作满12个月以上的, 当年度按在本单位剩余日历天数折算, 不足1整天不享受.
// 条例 第四条第(一)项; 实施办法 第七条: 寒暑假抵扣年休假, 多于年休假的不享受. 条例 第四条; 实施办法 第八条: 年度审核认定不享受的, 当年或下一年度无年休假.
// 条例 第五条; 实施办法 第九条: 跨年度安排只跨1个年度. 实施办法 第十条: 书面不休的天数不再计入.
const contract = ctx.subject.employment;
const started = get(contract, 'service_started_on', contract.effective_range.from);
const joined = get(contract, 'employment_started_on', contract.effective_range.from);
const facts = get(contract, 'employee_extension_data', {});
const reviews = get(facts, 'annual_leave_year_reviews', []);
const year = Number(ctx.as_of.slice(0, 4));
const review = (at) => first(reviews.filter((row) => row.year === at));
const band = ctx.lookup.service_bands.filter((row) => row.service_months <= calendar_completed_months(started, ctx.as_of)).at(-1);
const qualified = add_months(started, ctx.lookup.qualifying_service_months);
const from = joined > qualified ? joined : qualified;
const share = Number(from.slice(0, 4)) < year ? 1 : (calendar_distance_days(from, year + '-12-31') + 1) / ctx.lookup.first_year_proration_days;
const grant = band == null ? 0 : Math.floor(band.days * share);
const barred = get(review(year), 'disqualified', false) === true || get(review(year - 1), 'next_year_disqualified', false) === true;
const statutory = barred ? 0 : Math.max(0, grant - get(facts, 'school_vacation_days', 0));
const deferred = sum(reviews.filter((row) => row.year < year && row.year >= year - ctx.lookup.carry_forward_years).map((row) => row.deferred_days));
const spent = get(review(year), 'waived_days', 0) + get(review(year), 'deferred_days', 0);
return Math.max(0, statutory + deferred - spent);

SICK_LEAVE.paid_share:
// 沪劳保发〔1995〕83号: 连续休假6个月以内, 连续工龄不满2年60%, 满2年70%, 满4年80%, 满6年90%, 满8年100%; 超过6个月的疾病救济费, 不满1年40%, 满1年50%, 满3年60%. In force throughout this version.
// 劳部发〔1995〕309号 第59条; 沪劳保保发〔2000〕14号: 不低于最低工资的80%. 昆明市工资支付条例 第二十七条: 按有关规定支付. An agreed higher share binds.
const scheduled = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
const week = Number(get(ctx.subject.employment.terms, 'normal_days_per_week', 7 - scheduled.length));
const off = week === 7 - scheduled.length ? scheduled : [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - week);
const day = ctx.work.days.find((row) => row.date === ctx.as_of);
if (day == null ? off.includes(weekday(ctx.as_of)) : !['WORK', 'ABS'].includes(get(day, 'day_type', 'WORK'))) return 1;
const ext = get(ctx.subject.employer, 'entity_extension_data', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(ctx.subject.employment.terms, 'work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const zones = ctx.lookup.minimum_wage_by_zone.filter((row) => row.region === region);
if (zones.length === 0 || !(ctx.month_wage > 0)) return 1;
const zone = worksite !== '' && worksite !== employerRegion
  ? String(zones[0].default_zone)
  : String(get(ext, 'wage_zone', zones[0].default_zone));
const least = (ctx.lookup.minimum_wage_floor_share * zones.find((row) => row.zone === zone).monthly) / ctx.month_wage;
const agreed = Number(get(ctx.subject.employment, 'employee_extension_data.sick_pay_share', 0));
const scale = () => {
	if (region !== 'SH') return 0;
	const long = ctx.event != null && calendar_completed_months(ctx.event.on, ctx.as_of) >= ctx.lookup.shanghai_scale_first_months;
	const service = calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), ctx.as_of);
	return (long ? ctx.lookup.shanghai_scale_later : ctx.lookup.shanghai_scale_first).find((step) => step.completed_months == null || service <= step.completed_months).share;
};
return Math.min(1, Math.max(agreed, least, scale()));

lookup.entitlement:
// 女职工劳动保护特别规定 第七条: 98天, 其中产前可以休假15天; 难产增加15天; 多胞胎每多生育1个婴儿增加15天; 怀孕未满4个月流产15天, 满4个月流产42天.
const kind = ctx.event.kind;
const on = ctx.event.on;
if (kind === 'DIFFICULT_BIRTH') return ctx.lookup.difficult_birth_extra_days;
if (kind === 'ADDITIONAL_BABY') return ctx.lookup.additional_baby_extra_days;
const events = get(ctx.subject.employment, 'events', []);
const dates = (name) => events.filter((event) => event.kind === name).map((event) => event.on).toSorted();
if (kind === 'MISCARRIAGE') {
	const pregnancy = dates('PREGNANCY').filter((date) => date <= on).at(-1);
	return pregnancy != null && calendar_completed_months(pregnancy, on) >= ctx.lookup.miscarriage_month_threshold ? ctx.lookup.miscarriage_from_threshold_days : ctx.lookup.miscarriage_under_threshold_days;
}
if (kind === 'CONFINEMENT') {
	const birth = first(dates('CHILD_BIRTH').filter((date) => date >= on));
	return birth == null ? ctx.lookup.prenatal_days : Math.min(ctx.lookup.prenatal_days, calendar_distance_days(on, birth));
}
const start = dates('CONFINEMENT').filter((date) => date < on).at(-1);
const earlier = dates('CHILD_BIRTH').filter((date) => date < on).at(-1);
return ctx.lookup.grant_days - (start == null || (earlier != null && start <= earlier) ? 0 : Math.min(ctx.lookup.prenatal_days, calendar_distance_days(start, on)));

// 上海市人口与计划生育条例 第三十一条; 云南省人口与计划生育条例 第十八条: 符合规定生育的女方延长生育假60天.
const employerRegion = String(get(ctx.subject.employer, 'entity_extension_data.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
return get(first(ctx.lookup.days_by_region.filter((row) => row.region === region)), 'days', 0);

// 上海市人口与计划生育条例 第三十一条: 陪产假10天; 云南省人口与计划生育条例 第十八条: 护理假30天.
const employerRegion = String(get(ctx.subject.employer, 'entity_extension_data.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
return get(first(ctx.lookup.days_by_region.filter((row) => row.region === region)), 'days', 0);

// 上海市人口与计划生育条例 第三十一条: 增加婚假7天; 云南省人口与计划生育条例 第十八条: 增加婚假15天.
const employerRegion = String(get(ctx.subject.employer, 'entity_extension_data.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
return get(first(ctx.lookup.days_by_region.filter((row) => row.region === region)), 'days', 0);

// 上海市人口与计划生育条例 第三十一条: 子女年满3周岁前, 夫妻双方每年各5天 (不按子女数); 云南省人口与计划生育条例 第十八条: 子女不满3周岁每年10天, 两个以上15天.
const employerRegion = String(get(ctx.subject.employer, 'entity_extension_data.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const young = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'CHILD_BIRTH' && event.on <= ctx.as_of && age_on(event.on, ctx.as_of) < ctx.lookup.child_age_limit_years).length;
const each = first(ctx.lookup.per_child_days_by_region.filter((row) => row.region === region));
if (each != null) return each.days * young;
return get(ctx.lookup.days_by_children_by_region.filter((row) => row.region === region && row.children <= young).at(-1), 'days', 0);

