OVER_AGE_AGREEMENT.condition:
const key = 'OVER_AGE_AGREEMENT:' + ctx.entry.employment_id;
if (ctx.reads.obligation.some((task) => task.occurrence_key === key)) return false;
const run = first(ctx.reads.payroll_run);
if (run == null) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(ctx.subject.employment.engagement)) return false;
const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
if (born == null || born === '') return false;
const category =
get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
? get(ctx.subject.employment, 'employee_extension_data.retirement_category', 'FEMALE_50')
: 'MALE';
const retirement = ctx.lookup.retirement.find((row) => row.category === category);
const deferred =
born < retirement.cutoff
? 0
: Math.min(
retirement.max_deferral_months,
Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1
);
const retires = add_months(born, retirement.base_years * 12 + deferred);
if (run.salary_coverage.from < retires) return false;
return get(ctx.subject.employment, 'terms.signed_on', '') < retires;

