SICK_LEAVE.paid_share:
// 沪劳保发〔1995〕83号: 连续休假6个月以内, 连续工龄不满2年60%, 满2年70%, 满4年80%, 满6年90%, 满8年100%; 超过6个月的疾病救济费, 不满1年40%, 满1年50%, 满3年60%. In force to 2026-08-14 (this version).
// 劳部发〔1995〕309号 第59条; 沪劳保保发〔2000〕14号: 不低于最低工资的80%. 昆明市工资支付条例 第二十七条: 按有关规定支付. An agreed higher share binds.
const scheduled = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
const week = Number(get(ctx.subject.employment.terms, 'normal_days_per_week', 7 - scheduled.length));
const off = week === 7 - scheduled.length ? scheduled : [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - week);
const day = ctx.work.days.find((row) => row.date === ctx.as_of);
if (day == null ? off.includes(weekday(ctx.as_of)) : !['WORK', 'ABS'].includes(get(day, 'day_type', 'WORK'))) return 1;
const ext = get(ctx.subject.employer, 'entity_extension_data', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(ctx.subject.employment.terms, 'work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const zones = ctx.lookup.minimum_wage_by_zone.filter((row) => row.region === region);
if (zones.length === 0 || !(ctx.month_wage > 0)) return 1;
const zone = worksite !== '' && worksite !== employerRegion
  ? String(zones[0].default_zone)
  : String(get(ext, 'wage_zone', zones[0].default_zone));
const least = (ctx.lookup.minimum_wage_floor_share * zones.find((row) => row.zone === zone).monthly) / ctx.month_wage;
const agreed = Number(get(ctx.subject.employment, 'employee_extension_data.sick_pay_share', 0));
const scale = () => {
	if (region !== 'SH') return 0;
	const long = ctx.event != null && calendar_completed_months(ctx.event.on, ctx.as_of) >= ctx.lookup.shanghai_scale_first_months;
	const service = calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), ctx.as_of);
	return (long ? ctx.lookup.shanghai_scale_later : ctx.lookup.shanghai_scale_first).find((step) => step.completed_months == null || service <= step.completed_months).share;
};
return Math.min(1, Math.max(agreed, least, scale()));

UNEMPLOYMENT.eligibility:
const engagement = get(ctx.subject.employment, 'engagement', 'EMPLOYEE');
	const excluded = ['PART_TIME', 'INTERN', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);
	const end = get(ctx.subject.employment, 'effective_range.to', null);
	const ended = end != null && end !== '' && end < ctx.run.salary_coverage.from;
	const exempt = get(ctx.subject.employment, 'employee_extension_data.si_exempt_schemes', []);
	// a monthly charge: an off-cycle run carries only its own items
	if (get(ctx.run, 'kind', 'ON_CYCLE') === 'OFF_CYCLE') return false;
	if (excluded) return false;
	if (ended) return false;
	if (Array.isArray(exempt) && exempt.includes('UNEMPLOYMENT')) return false;
	const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
	if (born == null || born === '') return true;
	// 人社部令第56号 第十六条、第十七条: past the statutory retirement date this scheme stops, unless an agreement signed on or after that date declares a contribution base
	const category =
		get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
			? get(ctx.subject.employment, 'employee_extension_data.retirement_category', 'FEMALE_50')
			: 'MALE';
	const retirement = ctx.lookup.retirement.find((row) => row.category === category);
	const deferred =
		born < retirement.cutoff
			? 0
			: Math.min(
					retirement.max_deferral_months,
					Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1
				);
	const retires = add_months(born, retirement.base_years * 12 + deferred);
	if (ctx.run.salary_coverage.from < retires) return true;
	if (get(ctx.subject.employment, 'employee_extension_data.si_contribution_base', null) == null) return false;
	return get(ctx.subject.employment, 'terms.signed_on', '') >= retires;

